.settings-sidebar .nav-link:hover {
    background: #e9ecef;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
    border-left-color: #0d6efd;
}

.section-icon {
    font-size: 1.1rem;
}

/* ── Content area ── */

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    overflow-y: auto;
}

.section-heading {
    margin-bottom: 1.25rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

.setting-group {
    background: #f8f9fa;
    border-radius: 0.375rem;
    padding: 1rem 1.25rem;
}

/* ── Avatar ── */

.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
    flex-shrink: 0;
}

/* ── Toast ── */

.toast-notification {
    position: fixed;
    top: 1.5rem;
    right: 1.5rem;
    z-index: 9999;
    background: #198754;
    color: #fff;
    padding: 0.75rem 1.25rem;
    border-radius: 0.375rem;
