.toast-notification.toast-error {
    background: #dc3545;
}

@@keyframes toast-in {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Confirm dialog ── */

.confirm-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.4);
