toolArgs.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_cef3a46c0aa644049dc815e9a9c7f5ce.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="section-icon">@section.Value.Icon</span>
                        @section.Value.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="toast-notification @(_toastIsError ? "toast-error" : "")">
                    @_toastMessage
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

@* ── Confirmation dialog overlay ── *@
@if (_showConfirmDialog)
{
    <div class="confirm-overlay" @onclick="() => _showConfirmDialog = false">
        <div class="confirm-dialog" @onclick:stopPropagation="true">
            <h6>@_confirmTitle</h6>
            <p>@_confirmMessage</p>
            <div class="d-flex justify-content-end gap-2">
                <button class="btn btn-secondary btn-sm" @onclick="() => _showConfirmDialog = false">Cancel</button>
                <button class="btn btn-danger btn-sm" @onclick="ConfirmAction">Confirm</button>
            </div>
        </div>
    </div>
}

@code {
    // ── Section navigation ──
    private string ActiveSection { get; set; } = "profile";

    private readonly Dictionary<string, (string Label, string Icon)> _sections = new()
    {
        ["profile"] = ("Profile", "👤"),
        ["notifications"] = ("Notifications", "🔔"),
        ["security"] = ("Security", "🔒"),
        ["appearance"] = ("Appearance", "🎨"),
    };

    // ── Loading / toast ──
    private bool _loading = true;
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // ── Profile state ──
    private UserProfile _profile = default!;
    private UserProfile _savedProfile = default!;
    private string _editDisplayName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private string _editAvatarUrl = "";

    // ── Notification state ──
    private NotificationPrefs _notifPrefs = default!;
    private bool _editEmailNotif;
    private bool _editPushNotif;
    private bool _editWeeklyDigest;
    private List<(string Channel, bool Muted)> _editChannels = [];

    // ── Security state ──
    private SecuritySettings _security = default!;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _editTwoFactor;

    // ── Appearance state ──
    private AppearanceSettings _appearance = default!;
    private string _editTheme = "Light";
    private string _editFontSize = "Medium";
    private string _editLanguage = "English";
    private bool _editCompactMode;

    private static readonly string[] AvailableLanguages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    // ── Confirm dialog ──
    private bool _showConfirmDialog;
    private string _confirmTitle = "";
    private string _confirmMessage = "";
    private Func<Task>? _confirmCallback;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _savedProfile = _profile;
        LoadProfileEdits(_profile);

        _notifPrefs = await SettingsService.GetNotificationPrefsAsync();
        LoadNotifEdits(_notifPrefs);

        _security = await SettingsService.GetSecuritySettingsAsync();
        _editTwoFactor = _security.TwoFactorEnabled;

        _appearance = await SettingsService.GetAppearanceAsync();
        LoadAppearanceEdits(_appearance);

        _loading = false;
    }

    // ── Helpers ──

    private void LoadProfileEdits(UserProfile p)
    {
        _editDisplayName = p.DisplayName;
        _editEmail = p.Email;
        _editBio = p.Bio;
        _editAvatarUrl = p.AvatarUrl;
    }

    private void LoadNotifEdits(NotificationPrefs n)
    {
        _editEmailNotif = n.EmailNotifications;
        _editPushNotif = n.PushNotifications;
        _editWeeklyDigest = n.WeeklyDigest;
        _editChannels = n.MutedChannels.Select(c => (c, true)).ToList();
    }

    private void LoadAppearanceEdits(AppearanceSettings a)
    {
        _editTheme = a.Theme;
        _editFontSize = a.FontSize;
        _editLanguage = a.Language;
        _editCompactMode = a.CompactMode;
    }

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void ShowConfirm(string title, string message, Func<Task> callback)
    {
        _confirmTitle = title;
        _confirmMessage = message;
        _confirmCallback = callback;
        _showConfirmDialog = true;
    }

    private async Task ConfirmAction()
    {
        _showConfirmDialog = false;
        if (_confirmCallback is not null)
            await _confirmCallback();
    }

    // ── Profile actions ──

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editDisplayName, _editEmail, _editAvatarUrl, _editBio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _savedProfile = updated;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        LoadProfileEdits(_savedProfile);
    }

    // ── Notification actions ──

    private void ToggleChannelMute(int index)
    {
        var item = _editChannels[index];
        _editChannels[index] = (item.Channel, !item.Muted);
    }

    private async Task SaveNotifications()
    {
        var mutedChannels = _editChannels.Where(c => c.Muted).Select(c => c.Channel).ToList();
        var updated = new NotificationPrefs(_editEmailNotif, _editPushNotif, _editWeeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notifPrefs = updated;
        await ShowToast("Notification preferences saved!");
    }

    // ── Security actions ──

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _security = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(ActiveSession session)
    {
        ShowConfirm(
            "Revoke Session",
            $"Are you sure you want to revoke the session on \"{session.Device}\" in {session.Location}?",
            async () =>
            {
                await SettingsService.RevokeSessionAsync(session.Id);
                _security = await SettingsService.GetSecuritySettingsAsync();
                await ShowToast("Session revoked.");
            });
    }

    // ── Appearance actions ──

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_editTheme, _editFontSize, _editLanguage, _editCompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        await ShowToast("Appearance settings saved!");
    }

    // ── Render fragments ──

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h4 class="section-heading">Profile</h4>

        <div class="avatar-area mb-4">
            <img src="@_editAvatarUrl" alt="Avatar" class="avatar-preview" />
            <div class="mt-2">
                <label class="form-label">Avatar URL</label>
                <input class="form-control" @bind="_editAvatarUrl" />
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input class="form-control" @bind="_editDisplayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input class="form-control" type="email" @bind="_editEmail" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="3" @bind="_editBio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h4 class="section-heading">Notifications</h4>

        <div class="setting-group">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_editEmailNotif" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_editPushNotif" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_editWeeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <h6 class="mt-4 mb-3">Muted Channels</h6>
        <div class="setting-group">
            @for (var i = 0; i < _editChannels.Count; i++)
            {
                var index = i;
                var channel = _editChannels[index];
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" checked="@channel.Muted"
                           id="channel-@index" @onchange="() => ToggleChannelMute(index)" />
                    <label class="form-check-label" for="channel-@index">@channel.Channel</label>
                </div>
            }
        </div>

        <button class="btn btn-primary mt-3" @onclick="SaveNotifications">Save Preferences</button>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h4 class="section-heading">Security</h4>

        @* ── Change Password ── *@
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 style="cursor:pointer" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <span>Change Password</span>
                <span>@(_changePasswordExpanded ? "▲" : "▼")</span>
            </div>
            @if (_changePasswordExpanded)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input class="form-control" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input class="form-control" type="password" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input class="form-control" type="password" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>

                    @if (_security.LastPasswordChange.HasValue)
                    {
                        <small class="text-muted ms-3">
                            Last changed: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                        </small>
                    }
                </div>
            }
        </div>

        @* ── Two-Factor Authentication ── *@
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <span class="badge ms-2 @(_editTwoFactor ? "bg-success" : "bg-secondary")">
                        @(_editTwoFactor ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" @bind="_editTwoFactor" />
                </div>
            </div>
        </div>

        @* ── Active Sessions ── *@
        <h6>Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-striped align-middle">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _security.Sessions)
                    {
                        var isCurrent = session == _security.Sessions.First();
