            <label class="form-label fw-semibold">Language</label>
            <select class="form-select" style="max-width:250px" @bind="_editLanguage">
                @foreach (var lang in AvailableLanguages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        @* ── Compact Mode ── *@
        <div class="form-check form-switch mb-4">
            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_editCompactMode" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>

        @* ── Live Preview ── *@
        <div class="mb-4">
            <label class="form-label fw-semibold">Preview</label>
            <div class="appearance-preview @GetPreviewClasses()">
                <h6 style="margin-bottom:0.5rem">Sample Heading</h6>
                <p style="margin-bottom:0.5rem">This is how your content will look with the selected settings.</p>
                <button class="btn btn-primary btn-sm">Action Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (_editTheme == "Dark") classes.Add("preview-dark");
        if (_editFontSize == "Small") classes.Add("preview-small");
        if (_editFontSize == "Large") classes.Add("preview-large");
        if (_editCompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
